        <dt>People</dt>
        <dd data-testid="consolidated-people-count">{{ peopleCount() | fig }}</dd>
        <dt>Due</dt>
        <dd data-testid="consolidated-due-total">{{ dueTotal() | fig }}</dd>
        <dt>Overdue</dt>
